using LyricBridge;
public static class CompositionTests
{
    public static void Run() { void Check(bool b, string m) { if (!b) throw new Exception(m); } var a = new RichLyrics { Lines = [new() { Id = "a", Text = "Hello!", Start = 0 }, new() { Id = "b", Text = "World", Start = 10000000 }] }; var b = new RichLyrics { Lines = [new() { Id = "x", Text = "hello", Start = 0, Translations = new() { { "zh", "你好" } } }, new() { Id = "y", Text = "World", Start = 10000000, Translations = new() { { "zh", "世界" } } }] }; var map = LyricComposition.Suggest(a, b); Check(map["a"] == "x" && map["b"] == "y", "text and sequence alignment"); var mixed = LyricComposition.Mix(a, b, new("a", "b", "translation", "zh-Hans", map)); Check(mixed["b"] == "世界" && a.Lines[1].Start == 10000000, "language fallback and timing unchanged"); bool bad = false; try { LyricComposition.Mix(a, b, new("a", "b", "translation", "zh", new() { { "a", "y" }, { "b", "x" } })); } catch (ArgumentException) { bad = true; } Check(bad, "reject reordering"); b.Lines.Add(new() { Id = "z", Text = "hello", Start = 0 }); Check(!LyricComposition.Suggest(a, b).ContainsKey("a"), "ambiguous identical donor lines require manual mapping"); Console.WriteLine("PASS: source composition preserves timing and rejects ambiguous/reordered mappings."); }
}
